import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_good_numbers(limit=10000):
    good_numbers = set()

    # Iterate over G >= 2 (the GCD)
    G = 2
    while True:
        G_squared = G * G
        if G_squared > limit:
            break

        # Iterate over x' and y' such that 1 <= x' < y' and gcd(x', y') = 1
        # We can estimate an upper bound for y' based on the limit:
        # G^2 * (1^2 + y'^2) < limit  => y'^2 < limit/G^2 - 1
        max_y_prime = int((limit / G_squared - 1)**0.5) + 1

        for y_prime in range(2, max_y_prime):
            for x_prime in range(1, y_prime):
                if gcd(x_prime, y_prime) == 1:
                    m = G_squared * (x_prime**2 + y_prime**2)
                    if m < limit:
                        good_numbers.add(m)

        G += 1

    sorted_numbers = sorted(list(good_numbers))
    return sorted_numbers

# We need the 20th smallest. Let's set a high limit initially to ensure we capture it.
# Based on the manual check, the numbers grow somewhat slowly. 10000 should be plenty.
result = find_good_numbers(limit=10000)

print(f"Total good numbers found below 10000: {len(result)}")
print("The first 30 good numbers:")
for i, num in enumerate(result[:30]):
    print(f"{i+1}: {num}")

if len(result) >= 20:
    print(f"\nThe 20th smallest good number is: {result[19]}")
else:
    print("\nNot enough numbers found below the limit.")
